query:


fragment AccommodationIdFields on Accommodation {
  contentKey
  dedupId
  key
}


fragment SearchPriceBreakdown on PriceBreakdown {
  __typename
  price
  priceRounded
  priceWithoutDiscount
  priceWithoutDiscountRounded
  pricePerNight
  pricePerNightRounded
  pricePerNightWithoutDiscount
  pricePerNightWithoutDiscountRounded
  discount {
    percentage
    packageAmount
    packageAmountRounded
    primeAmount
    primeAmountRounded
    publicAmount
    publicAmountRounded
  }
}

fragment AccommodationFields on Accommodation {
  ...AccommodationIdFields
  secretHotelId
  debugInfo
  providerId
  roomsLeft
  distanceFromCityCenter
  insideDestination
  cancellationFreeAlternativeAvailable
  priceBreakdown {
    ...SearchPriceBreakdown
  }
  accommodationFacilities
  accommodationDeal {
    hasMerchandisePrice
    neighbourhood
    name
    cityName
    address
    description
    coordinates {
      latitude
      longitude
    }
    cancellationFree
    paymentAtDestination
    category
    chain
    type
    mainAccommodationImage {
      url
    }
    payLaterAvailable
  }
  userReview {
    rating
    totalReviews
  }
  roomOffer {
    hasDiscount
    taxesAndFeesDescription
    retailStrategy {
      highlightType
      primeDiscountType
      showAbsoluteDiscount
      showPercentageDiscount
      isPromoCodeApplicable
    }
  }
  sortingLogic {
    defaultPosition
    personalisationApplied
  }
  boardType
  favorite
  snippet
}


fragment AccommodationSearchMetadata on AccommodationSearchMetadata {
  priceMetadata {
    maxPrice
    minPrice
    avgPrice
    maxDiscountPercentage
    pricePerNightRange
    maxPricePerNight
    minPricePerNight
    avgPricePerNight
    maxSavingAmount
  }
  priceFilter {
    pricePerNight {
      step
      numSteps
    }
  }
  filtersMetadata {
    filterName
    filterType
    count
  }
  availabilityMetadata {
    unavailablePropertiesPercentage
  }
}

query searchAccommodation(
  $accommodationSearchRequest: AccommodationSearchRequest!
)  {
  searchAccommodation(
    accommodationSearchRequest: $accommodationSearchRequest
  ) {
    searchId
    currency
    accommodations {
      ...AccommodationFields
    }
    metadata {
      ...AccommodationSearchMetadata
    }
  }
}
